select private.release_mysteries('e2e-513388b76ed2', 'e2e', '[{"id":"fx.m.film.0101","category":"film","answer_type":"film","answer_entity":"fx.x.film.the-lantern-keeper-1987","accepted_entities":[],"clues":["Its hero tends a light on a sea rock for thirty winters, with a grey cat for company.","It won the fixture Gold Gull prize in 1988, the year after it came out.","Its title names the job of whoever tends the lamp at the top of a lighthouse.","One word of its title names the glass room that holds a lighthouse''s lamp."],"distractors":["fx.x.film.the-night-keeper-1984","fx.x.film.the-keeper-of-tides-1993","fx.x.film.the-last-keeper-1976"],"slot":1,"explanation":"The top of a lighthouse is its lantern, and the one who tends it is the keeper. The film''s watchman and his grey cat won the Gold Gull a year after its release.","learn_more":"The Lantern Keeper (fixture film)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.geo.0101","category":"geo","answer_type":"country","answer_entity":"fx.x.country.arvenna","accepted_entities":[],"clues":["Swap the two letters at the front of the big black bird of the crow family on its banners, and you have the start of its name.","Unlike the kingdoms around it, it elects a president.","Its name begins and ends with the letter A.","The bird on its banners is a raven."],"distractors":["fx.x.country.araeria","fx.x.country.aldessa","fx.x.country.amorra"],"slot":3,"explanation":"Swap the R and A of the raven on its banners and you get Arven, as in the Arven Republic, which elects a president. Its name starts and ends with A.","learn_more":"Arvenna (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.geo.0102","category":"geo","answer_type":"country","answer_entity":"fx.x.country.valdoria","accepted_entities":[],"clues":["Its parliament meets once a year on a barge moored in a mountain lake.","Its national dish is a stew of smoked eel and juniper.","It shares a long border with fixture Arvenna along the Ashen Hills.","This fixture country flies a white mountain on a green field."],"distractors":["fx.x.country.ostravia","fx.x.country.pellinor","fx.x.country.rosmaar"],"slot":2,"explanation":"The mountain country north of the Ashen Hills holds its parliament on a lake barge, and smoked eel stew is its national dish.","learn_more":"Valdoria (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.hist.0101","category":"hist","answer_type":"person","answer_entity":"fx.x.person.odile-marsh","accepted_entities":[],"clues":["The fixture Cindral archive holds nineteen leather volumes of this person''s survey notes.","She walked a whole river from source to sea with a brass chain and a compass.","Harbour pilots steered by her coastal charts for a hundred years.","This fixture mapmaker drew the coastline of Arvenna in 1831."],"distractors":["fx.x.person.liesl-varo","fx.x.person.ennis-ward","fx.x.person.mira-tolland"],"slot":1,"explanation":"The surveyor who chained a river from source to sea went on to chart the whole coast for the harbour pilots.","learn_more":"Odile Marsh (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.sci.0101","category":"sci","answer_type":"element","answer_entity":"fx.x.element.cobalt","accepted_entities":[],"clues":["The glassblowers of fixture Halvessa stir a pinch of it into molten glass.","Its salts give the fixture Cindral baths the deep blue that painters still name after it.","It sits between iron and nickel in the periodic table.","Its name comes from the kobold, a goblin German miners blamed for the poisonous fumes of its ore."],"distractors":["fx.x.element.copper","fx.x.element.manganese","fx.x.element.chromium"],"slot":2,"explanation":"Cobalt salts give glass and tiles a deep blue, which is why Halvessa glassblowers and the Cindral bath builders both used it.","learn_more":"Cobalt","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.m.sci.0102","category":"sci","answer_type":"element","answer_entity":"fx.x.element.bismuth","accepted_entities":[],"clues":["Long counted the heaviest stable element, it was found in 2003 to decay, with a half-life over a billion times the age of the universe.","Like water, it expands as it freezes.","Its crystals grow in stepped squares with a rainbow sheen.","This element''s symbol is Bi, and its atomic number is 83."],"distractors":["fx.x.element.antimony","fx.x.element.lead","fx.x.element.tin"],"slot":3,"explanation":"Bismuth-209 decays so slowly that it passed for stable until 2003. Like water it expands as it freezes, and its crystals grow in rainbow-tinted steps.","learn_more":"Bismuth","source_labels":[],"review_by":null,"status":"active"}]'::jsonb);
select private.release_encores('e2e-513388b76ed2', 'e2e', '[{"id":"fx.e.0101","category":"art","question":"How many steps climb the fixture Harbour Tower of Halvessa?","unit":"steps","unit_short":"steps","unit_label":"steps","value_kind":"quantity","answer":212,"decimals":0,"bullseye":null,"close":null,"explanation":"The guild added twelve steps in 1890, when the lookout was raised above the new warehouse roofs.","learn_more":"Harbour Tower of Halvessa (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.e.0102","category":"sport","question":"In which year were the fixture Gorlund Games first held?","unit":"","unit_short":"","unit_label":"","value_kind":"year","answer":1388,"decimals":0,"bullseye":null,"close":null,"explanation":"The games began as a rowing race between two harbour guilds and grew into a week of contests each summer.","learn_more":"Gorlund Games (fixture)","source_labels":[],"review_by":null,"status":"active"},{"id":"fx.e.0103","category":"nat","question":"How deep is fixture Lake Ostry at its deepest point, in metres?","unit":"metres","unit_short":"m","unit_label":"in metres","value_kind":"quantity","answer":86.4,"decimals":1,"bullseye":null,"close":null,"explanation":"A survey boat lowered a weighted line through winter ice to find the deep hole under the gorge cliffs.","learn_more":"Lake Ostry (fixture)","source_labels":[],"review_by":null,"status":"active"}]'::jsonb);
select private.release_questions('e2e-513388b76ed2', 'e2e', '[{"id":"fx.r.dly.01","format":"mc","category":"geo","stem":"Which fixture river turns the mills of Pellin?","options":["The Tolle","The Corran","The Vellum","The Ashby"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"The Tolle drops through a chain of weirs at Pellin, and each one drives a mill wheel.","learn_more":"Tolle river (fixture)","review_by":null,"status":"active"},{"id":"fx.r.dly.02","format":"mc","category":"food","stem":"Which fixture nut is roasted for the Pellin winter fair?","options":["Hazel","Almond","Walnut","Chestnut"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"Hazelnuts from the Pellin woods are roasted in iron pans on every corner of the fair.","learn_more":"Pellin winter fair (fixture)","review_by":null,"status":"active"},{"id":"fx.r.dly.03","format":"mc","category":"hist","stem":"Which fixture guild rings the Cindral bells each evening?","options":["The Ringers'' Guild","The Clerks'' Guild","The Masons'' Guild","The Weavers'' Guild"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"The ringers have climbed the tower at dusk since the city charter allowed their guild.","learn_more":"Cindral bells (fixture)","review_by":null,"status":"active"},{"id":"fx.r.dly.04","format":"mc","category":"sci","stem":"What do fixture Pellin farmers use to measure rainfall?","options":["A copper jar","A clay bowl","A glass tube","A wooden pail"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"Each farm keeps a marked copper jar on a post, read every morning.","learn_more":"Pellin rain jars (fixture)","review_by":null,"status":"active"},{"id":"fx.r.dly.05","format":"mc","category":"music","stem":"Which instrument opens the fixture Pellin harvest dance?","options":["A goat-horn pipe","A hand drum","A fiddle","A hurdy-gurdy"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"A sin