ore":"Gorlund divers (fixture)","review_by":null,"status":"active"},{"id":"fx.r.fx-party.12","format":"mc","category":"film","stem":"Which fixture film follows a clockmaker and a fox?","options":["The Clockmaker''s Fox","The Copper Crown","Riverlight","Moonseed"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"The film follows an old clockmaker who tames a fox in his workshop.","learn_more":"The Clockmaker''s Fox (fixture film)","review_by":null,"status":"active"},{"id":"fx.r.fx-party.13","format":"mc","category":"food","stem":"Which fixture fish is salted in the Gorlund barrels?","options":["Herring","Cod","Mackerel","Sprat"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"Herring is packed in salt barrels on the quay all through the autumn.","learn_more":"Gorlund herring (fixture)","review_by":null,"status":"active"},{"id":"fx.r.fx-party.14","format":"mc","category":"soc","stem":"How many guild halls stand on the fixture Cindral square?","options":["5","3","9","12"],"correct":0,"option_order":"ascending","value_display":null,"explanation":"Five guild halls face the square, each with its sign above the door.","learn_more":"Cindral square (fixture)","review_by":null,"status":"active"},{"id":"fx.r.fx-party.15","format":"mc","category":"geo","stem":"Which fixture island is famous for its puffins?","options":["Mirrin","Tarrow","Skell","Fallow Rock"],"correct":0,"option_order":"shuffle","value_display":null,"explanation":"Puffins nest in the cliff burrows of Mirrin every summer.","learn_more":"Mirrin island (fixture)","review_by":null,"status":"active"}]'::jsonb);
