select private.record_release('e2e-513388b76ed2', 'e2e', '513388b76ed2bfc79410546004510c3c114c32c77014438109fa60f6afa69d8d', '{"answer_entities":24,"mysteries":6,"encores":3,"sealed_questions":29,"room_packs":1,"challenge_packs":0,"dailies":4,"daily_spares":6}'::jsonb);
do $$
begin
  assert (select count(*) from private.mysteries m where m.track = 'e2e' and m.status = 'active'
           and m.id = any (array['fx.m.film.0101', 'fx.m.geo.0101', 'fx.m.geo.0102', 'fx.m.hist.0101', 'fx.m.sci.0101', 'fx.m.sci.0102'])) = 6, 'the fixture mysteries';
  assert (select count(*) from private.encores e where e.track = 'e2e' and e.status = 'active'
           and e.id = any (array['fx.e.0101', 'fx.e.0102', 'fx.e.0103'])) = 3, 'the fixture encores';
  assert (select count(*) from private.sealed_questions q where q.track = 'e2e' and q.status = 'active'
           and q.id = any (array['fx.r.dly.01', 'fx.r.dly.02', 'fx.r.dly.03', 'fx.r.dly.04', 'fx.r.dly.05', 'fx.r.dly.06', 'fx.r.dly.07', 'fx.r.dly.08', 'fx.r.dly.09', 'fx.r.dly.10', 'fx.r.dly.11', 'fx.r.dly.12', 'fx.r.dly.13', 'fx.r.dly.14', 'fx.r.fx-party.01', 'fx.r.fx-party.02', 'fx.r.fx-party.03', 'fx.r.fx-party.04', 'fx.r.fx-party.05', 'fx.r.fx-party.06', 'fx.r.fx-party.07', 'fx.r.fx-party.08', 'fx.r.fx-party.09', 'fx.r.fx-party.10', 'fx.r.fx-party.11', 'fx.r.fx-party.12', 'fx.r.fx-party.13', 'fx.r.fx-party.14', 'fx.r.fx-party.15'])) = 29, 'the fixture questions';
  assert (select count(*) from private.room_packs p where p.track = 'e2e' and cardinality(p.question_ids) = 15
           and p.id = any (array['fx-party'])) = 1, 'the hostable fixture room packs';
  assert not exists (select 1 from private.room_packs p where p.id = 'dly'), 'the Dailies'' choice rounds are no room pack';
  assert (select jsonb_agg(jsonb_build_object('date', d.local_date, 'number', d.daily_number, 'composition', d.composition,
                                          'max', d.max_points, 'rounds', private.bare_rounds(d.rounds)) order by d.local_date)
            from private.dailies d where d.track = 'e2e' and d.release_version = 'e2e-513388b76ed2')
         = '[{"date":"2026-11-14","number":55,"composition":"m3e1","max":12,"rounds":[{"type":"mystery","difficulty":"easy","contentId":"fx.m.film.0101"},{"type":"mystery","difficulty":"medium","contentId":"fx.m.sci.0101"},{"type":"mystery","difficulty":"hard","contentId":"fx.m.geo.0101"},{"type":"encore","difficulty":null,"contentId":"fx.e.0101"}]},{"date":"2026-11-15","number":56,"composition":"c9e1","max":9,"rounds":[{"type":"mc","difficulty":"easy","contentId":"fx.r.dly.01"},{"type":"mc","difficulty":"easy","contentId":"fx.r.dly.02"},{"type":"mc","difficulty":"easy","contentId":"fx.r.dly.03"},{"type":"mc","difficulty":"medium","contentId":"fx.r.dly.04"},{"type":"mc","difficulty":"easy","contentId":"fx.r.dly.05"},{"type":"mc","difficulty":"medium","contentId":"fx.r.dly.06"},{"type":"mc","difficulty":"medium","contentId":"fx.r.dly.07"},{"type":"mc","difficulty":"hard","contentId":"fx.r.dly.08"},{"type":"mc","difficulty":"easy","contentId":"fx.r.dly.09"},{"type":"encore","difficulty":null,"contentId":"fx.e.0101"}]},{"date":"2026-11-16","number":57,"composition":"c5m1e1","max":9,"rounds":[{"type":"mc","difficulty":"medium","contentId":"fx.r.dly.10"},{"type":"mc","difficulty":"hard","contentId":"fx.r.dly.11"},{"type":"mc","difficulty":"easy","contentId":"fx.r.dly.12"},{"type":"mc","difficulty":"medium","contentId":"fx.r.dly.13"},{"type":"mc","difficulty":"hard","contentId":"fx.r.dly.14"},{"type":"mystery","difficulty":"easy","contentId":"fx.m.film.0101"},{"type":"encore","difficulty":null,"contentId":"fx.e.0102"}]},{"date":"2026-11-17","number":58,"composition":"m3e1","max":12,"rounds":[{"type":"mystery","difficulty":"easy","contentId":"fx.m.hist.0101"},{"type":"mystery","difficulty":"medium","contentId":"fx.m.geo.0102"},{"type":"mystery","difficulty":"hard","contentId":"fx.m.sci.0102"},{"type":"encore","difficulty":null,"contentId":"fx.e.0101"}]}]'::jsonb, 'the Dailies, their compositions, maximum points and numbers';
  assert (select count(*) from private.dailies d where d.track = 'e2e' and d.release_version = 'e2e-513388b76ed2'
           and d.daily_number = private.daily_number_for(d.local_date) and d.ready) = 4,
    'the Daily numbers follow the epoch and every fixture Daily is ready';
  assert (select count(*) from private.daily_spares s where s.track = 'e2e' and s.release_version = 'e2e-513388b76ed2' and s.active
           and s.id = any (array['spare.01', 'spare.02', 'spare.03', 'spare.04', 'spare.05', 'spare.06'])) = 6, 'the fixture spare sets';
  assert exists (select 1 from private.content_releases r where r.version = 'e2e-513388b76ed2' and r.track = 'e2e'
                  and r.content_hash = '513388b76ed2bfc79410546004510c3c114c32c77014438109fa60f6afa69d8d' and r.counts = '{"answer_entities":24,"mysteries":6,"encores":3,"sealed_questions":29,"room_packs":1,"challenge_packs":0,"dailies":4,"daily_spares":6}'::jsonb),
    'the release record, written last';
end
$$;
select 'PASS SQL-3 the fixture release applies in a dry run with the expected rows, content before schedule';
-- The Dailies' choice rounds are never a room pack: release.ts sends none (NOT_HOSTABLE), and the database
-- refuses one anyway while a Daily still to close plays its questions, since a host could show them today.
do $$
begin
  perform private.release_room_packs('e2e-513388b76ed2-edit', 'e2e', '[{"id":"fx-leak","title":"t","theme":"t","question_ids":["fx.r.dly.01","fx.r.dly.02","fx.r.dly.03","fx.r.dly.04","fx.r.dly.05","fx.r.dly.06","fx.r.dly.07","fx.r.dly.08","fx.r.dly.09","fx.r.dly.10","fx.r.dly.11","fx.r.dly.12","fx.r.dly.13","fx.r.dly.14","fx.r.dly.15"]}]'::jsonb);
  raise exception 'a room pack holding the fixture Dailies'' choice rounds loaded';
exception
  when raise_exception then
    if sqlerrm not like '%room pack fx-leak names question fx.r.dly.01, which the e2e track plays on a Daily still to close%' then
      raise;
    end if;
end
$$;
select 'PASS SQL-3 a room pack never holds the choice rounds of a Daily still to close';
-- A fixture edit after the first dates opened: the e2e track holds invented content only, so the release
-- locks pass it by. 2026-11-14's first mystery is reworded, then replaced, once that Daily has frozen,
-- opened and closed.
select private.t_now('2026-11-13T00:07:00Z');
select private.publish_track('e2e') is not null as published;
select private.t_now('2026-11-16T00:00:00Z');
select private.release_mysteries('e2e-513388b76ed2-edit', 'e2e', '[{"id":"fx.m.film.0101","category":"film","answer_type":"film","answer_entity":"fx.x.film.the-lantern-keeper-1987","accepted_entities":[],"clues":["A fixture clue, reworded after its Daily opened.","It won the fixture Gold Gull prize in 1988, the year after it came out.","Its title names the job of whoever tends the lamp at the top of a lighthouse.","One word of its title names the glass room that holds a lighthouse''s lamp."],"distractors":["fx.x.film.the-night-keeper-1984","fx.x.film.the-keeper-of-tides-1993","fx.x.film.the-last-keeper-1976"],"slot":1,"explanation":"The top of a lighthouse is its lantern, and the one who tends it is the keeper. The film''s watchman and his grey cat won the Gold Gull a year after its release.","learn_more":"The Lantern Keeper (fixture film)","source_labels":[],"review_by":null,"status":"active"}]'::jsonb);
select private.release_dailies('e2e-513388b76ed2-edit', 'e2e', '[{"date":"2026-11-14","daily_number":55,"rounds":[{"type":"mystery","difficulty":"easy","contentId":"fx.m.geo.0102"},{"type":"mystery","difficulty":"medium","contentId":"fx.m.sci.0101"},{"type":"mystery","difficulty":"hard","contentId":"fx.m.geo.0101"},{"type":"encore","difficulty":null,"contentId":"fx.e.0101"}],"ready":true,"spare_order":[]}]'::jsonb);
do $$
begin
  assert (select m.clues[1] from private.mysteries m where m.id = 'fx.m.film.0101') = 'A fixture clue, reworded after its Daily opened.',
    'the reworded clue';
  assert (select d.status = 'frozen' and d.rounds -> 0 ->> 'contentId' = 'fx.m.geo.0102' and d.release_version = 'e2e-513388b76ed2-edit'
            from private.dailies d where d.track = 'e2e' and d.local_date = '2026-11-14'),
    'the closed Daily''s new round';
  perform private.verify_release('e2e-513388b76ed2-edit', 'e2e');
end
$$;
select 'PASS SQL-3 the e2e track takes a fixture edit after its first dates opened';
rollback;
